using System; using System.Security.Principal;
namespace OrderFlow.MVC.Security { [Serializable] public class CustomPrincipalSerializeModel { public int UserId { get; set; } public int? CustomerId { get; set; } public string DisplayName { get; set; } public string Role { get; set; } } public class CustomPrincipal : IPrincipal { public IIdentity Identity { get; private set; } public int UserId { get; private set; } public int? CustomerId { get; private set; } public string DisplayName { get; private set; } public string Role { get; private set; } public CustomPrincipal(string email, int userId, int? customerId, string displayName, string role) { Identity = new GenericIdentity(email); UserId = userId; CustomerId = customerId; DisplayName = displayName; Role = role; } public bool IsInRole(string role) { return string.Equals(Role, role, StringComparison.OrdinalIgnoreCase); } } }
